"""The tp4/sched-2 window pack (scripts/ci/references/fusion-jobs/SCH2, generated by make_sched2_jobs.py).

ORDER.txt lists exactly the folder's templates, each once, on the one image, with a total that matches its header; every NEEDS line names earlier jobs; every smoke job carries the two Swift
checkpoint keys; every pair differs by the profile alone; every template parses through the job reader with rc 0; the pack is what the generator makes; nothing in it names a host, an
address or a registry; every test it names is in the smoke runner of this tree (agent_turns included: it is merged)."""

import json
from pathlib import Path
import re
import subprocess
import sys
import unittest

HERE = Path(__file__).resolve().parent
if str(HERE) not in sys.path:
    sys.path.insert(0, str(HERE))

import c2_serving_job as job  # noqa: E402
import make_sched2_jobs as pack  # noqa: E402
import make_sched2_profiles as twins  # noqa: E402

PACK = pack.FOLDER
READER = HERE / 'c2_serving_job.py'
PROFILES = HERE / 'qwen_c2_profiles.json'
CATALOG = json.loads((HERE / 'qwen_c2_checkpoints.json').read_text(encoding='utf-8'))
SWIFT = CATALOG['checkpoints'][0]
ARM = pack.ARM

# job -> (mode, serves Swift, profile, smoke tests)
EXPECTED = {
    'B0-build-window': ('stop', False, '', ''),
    'X0-status-rescan-reset': ('stop', False, '', ''),
    'A1-sch2-audited-attach': ('stop', True, ARM['audit'], pack.AUDIT_TESTS),
    'C1-control-a': ('soft', True, pack.SHIP, pack.TIMED_TESTS),
    'L1-all-a': ('soft', True, ARM['all'], pack.TIMED_TESTS),
    'C2-control-b': ('soft', True, pack.SHIP, pack.TIMED_TESTS),
    'L2-all-b': ('soft', True, ARM['all'], pack.TIMED_TESTS),
    'SE1-seed-a': ('soft', True, ARM['seed'], pack.TIMED_TESTS),
    'HO1-hold-a': ('soft', True, ARM['hold'], pack.TIMED_TESTS),
    'LT1-ledger-a': ('soft', True, ARM['ledger'], pack.TIMED_TESTS),
    'Z-reset': ('soft', False, '', ''),
}


def order_lines():
    return [line.split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.strip() and not line.startswith('#')]


def directives(prefix):
    return [line[len(prefix):].split() for line in (PACK / 'ORDER.txt').read_text(encoding='utf-8').splitlines() if line.startswith(prefix)]


def values(name):
    return job.parse_env((PACK / (name + '.env')).read_text(encoding='utf-8'))


def run_reader(path):
    result = subprocess.run([sys.executable, '-B', '-s', str(READER), str(path), str(PROFILES)], stdout=subprocess.PIPE, stderr=subprocess.PIPE, cwd=str(HERE.parent.parent))
    return result.returncode, (result.stdout + result.stderr).decode('utf-8', 'replace')


class OrderTests(unittest.TestCase):
    def test_order_lists_exactly_the_folders_templates_once_on_one_image(self):
        rows = order_lines()
        self.assertEqual([row[0] for row in rows], list(EXPECTED), 'in value order')
        self.assertEqual(sorted(path.stem for path in PACK.glob('*.env')), sorted(EXPECTED))
        self.assertEqual({row[2] for row in rows}, {pack.IMAGE})
        self.assertEqual(pack.IMAGE, 'tp4-sched-2')
        for row in rows:
            self.assertEqual(row[1], EXPECTED[row[0]][0], row[0])
            self.assertEqual(values(row[0])['C2_IMAGE_TAG'], pack.IMAGE)

    def test_the_header_total_matches_the_minutes_and_the_shortest_window_is_named(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        rows = order_lines()
        minutes = sum(int(row[3]) for row in rows)
        self.assertIn('%d minutes (%d h %d min) in all' % (minutes, minutes // 60, minutes % 60), text)
        for row in rows:
            self.assertIn('%s %s' % (row[0].split('-')[0], row[3]), text)
        shortest = sum(int(row[3]) for row in rows if row[0].split('-')[0] in ('X0', 'A1', 'C1', 'L1', 'Z'))
        self.assertIn('X0 A1 C1 L1 Z: %d minutes of cards' % shortest, text)

    def test_needs_lines_name_earlier_jobs_only(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        for left_right in directives('# NEEDS '):
            arrow = left_right.index('<-')
            left, right = left_right[:arrow], left_right[arrow + 1:]
            for job_name in left + right:
                self.assertIn(job_name, names)
            for later in left:
                for earlier in right:
                    self.assertLess(names.index(earlier), names.index(later), left_right)
        needed = {token for line in directives('# NEEDS ') for token in line[:line.index('<-')]}
        self.assertEqual(needed, set(names) - {'B0', 'Z'}, 'every serving job waits for something; the build and the reset wait for nothing')

    def test_the_arc_range_covers_every_audited_and_timed_boot_and_nothing_else(self):
        names = [row[0].split('-')[0] for row in order_lines()]
        ((first, last),) = directives('# ARC-ZERO ')
        self.assertEqual((first, last), ('A1', 'LT1'))
        for token in names:
            inside = names.index(first) <= names.index(token) <= names.index(last)
            self.assertEqual(inside, token not in ('B0', 'X0', 'Z'), token)

    def test_the_order_says_what_is_unqualified_what_decides_and_where_it_merges(self):
        text = (PACK / 'ORDER.txt').read_text(encoding='utf-8')
        for phrase in ('Never cancel a running card job', 'UNQUALIFIED', 'owner traffic waiver', 'agent_turns', "the owner's, never the window's", 'MERGE POINTS', 'levern_policy.py', 'tp4/next-2'):
            self.assertIn(phrase, text)
        for name in EXPECTED:
            self.assertIn('no tag is pushed from the branch by its author', (PACK / (name + '.env')).read_text(encoding='utf-8'))

    def test_every_test_the_pack_names_is_in_the_smoke_runner_of_this_tree(self):
        smoke = (HERE / 'c2_serving_smoke.py').read_text(encoding='utf-8')
        named = {test for _mode, _swift, _profile, tests in EXPECTED.values() for test in filter(None, tests.split(','))}
        self.assertEqual({test for test in named if "def %s(" % test not in smoke and "'%s'" % test not in smoke}, set())


class TemplateTests(unittest.TestCase):
    def test_every_template_parses_with_rc_0(self):
        for name in EXPECTED:
            with self.subTest(name=name):
                code, text = run_reader(PACK / (name + '.env'))
                self.assertEqual(code, 0, text)

    def test_serving_jobs_carry_the_checkpoint_keys_and_the_expected_profile_and_tests(self):
        for name, (_mode, serves_swift, profile, tests) in EXPECTED.items():
            with self.subTest(name=name):
                found = values(name)
                if serves_swift:
                    self.assertEqual((found['C2_MODEL_REPO'], found['C2_MODEL_REVISION']), (SWIFT['repo'], SWIFT['revision']))
                    self.assertEqual((pack.REPO, pack.REVISION), (SWIFT['repo'], SWIFT['revision']))
                else:
                    self.assertNotIn('C2_MODEL_REPO', found)
                    self.assertNotIn('C2_MODEL_REVISION', found)
                self.assertEqual(found.get('C2_PROFILE', ''), profile)
                self.assertEqual(found.get('C2_SMOKE_TESTS', ''), tests)

    def test_every_profile_a_job_names_is_a_twin_or_the_candidate(self):
        profiles = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles']
        for name in EXPECTED:
            found = values(name).get('C2_PROFILE')
            if found:
                self.assertIn(found, profiles, name)
                self.assertIn(found, set(twins.NAMES) | {pack.SHIP}, name)

    def test_no_job_uses_a_step_that_does_not_forward_the_checkpoint_when_it_carries_it(self):
        for name in EXPECTED:
            found = values(name)
            actions = set(found['C2_ACTIONS'].split())
            if found.get('C2_MODEL_REPO'):
                self.assertFalse(actions - set(job.MODEL_ACTIONS), name)
            self.assertFalse(actions & {'gate', 'replay', 'push', 'agentstop', 'agentstart', 'unserve', 'platform', 'prefix'}, name)

    def test_the_build_bakes_the_approved_ship_5_candidate_with_the_oneq_graft_and_never_a_twin(self):
        found = values('B0-build-window')
        self.assertEqual((found['C2_BAKE_DEFAULT_PROFILE'], found['C2_BAKE_GRAFT']), (pack.SHIP, 'K64j-OQ'))
        entry = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][pack.SHIP]
        self.assertFalse(job.bake_waiver_pending(entry), 'the ship-5 waiver is APPROVED: the build is not refused')
        for name in EXPECTED:
            if name != 'B0-build-window':
                self.assertNotIn('C2_BAKE_DEFAULT_PROFILE', values(name), name)

    def test_the_pairs_differ_by_the_profile_alone_and_the_control_is_the_candidate(self):
        keys = ('C2_SMOKE_TESTS', 'C2_BOX_MINUTES', 'C2_IMAGE_TAG', 'C2_MODEL_REPO', 'C2_MODEL_REVISION', 'C2_CARDS', 'C2_ACTIONS', 'C2_TELEMETRY')
        for control, arm in (('C1-control-a', 'L1-all-a'), ('C2-control-b', 'L2-all-b'), ('C1-control-a', 'SE1-seed-a'), ('C1-control-a', 'HO1-hold-a'), ('C1-control-a', 'LT1-ledger-a')):
            self.assertEqual([values(control).get(key) for key in keys], [values(arm).get(key) for key in keys], (control, arm))
            self.assertEqual(values(control)['C2_PROFILE'], pack.SHIP)

    def test_each_smoke_job_names_the_steady_test_right_after_the_warmup_and_a_box_inside_the_step(self):
        for name, (_mode, _swift, _profile, tests) in EXPECTED.items():
            found = values(name)
            if 'smoke' not in found['C2_ACTIONS'].split():
                continue
            with self.subTest(name=name):
                names = tests.split(',')
                self.assertIn('concurrent8_steady', names)
                self.assertIn('agent_turns', names)
                if name != 'A1-sch2-audited-attach':
                    self.assertEqual(names[:2], ['warmup', 'concurrent8_steady'], 'the burst into a fresh process comes first: the first-use costs are only visible there')
                self.assertTrue(0 < int(found['C2_BOX_MINUTES']) <= 210)
                self.assertGreater(int(found['C2_BOX_MINUTES']), int(dict((row[0], row[3]) for row in order_lines())[name]) - 1, 'the box is not shorter than the estimate')
                self.assertEqual(found['C2_CARDS'], 'quad')
                self.assertEqual(found['C2_TELEMETRY'], '1')

    def test_the_audited_attach_runs_the_audit_arm_with_the_two_order_levers_and_not_the_ledger_trim(self):
        found = values('A1-sch2-audited-attach')
        self.assertEqual(found['C2_PROFILE'], ARM['audit'])
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'A1-sch2-audited-attach.env').read_text(encoding='utf-8'))
        for phrase in ('the seed token leaves the engine before', 'the DRAM hold reuses a recent allocator reading', 'NOT_EXERCISED', 'no "audit mismatch"'):
            self.assertIn(phrase, text)
        profile = json.loads(PROFILES.read_text(encoding='utf-8'))['profiles'][ARM['audit']]
        self.assertNotIn('QWEN_FAST_ADMISSION_LEDGER_TRIM', profile['env'])

    def test_the_templates_name_the_readers_the_lines_and_the_estimates(self):
        text = re.sub(r'\s*\n#\s*', ' ', (PACK / 'L1-all-a.env').read_text(encoding='utf-8'))
        for phrase in ('sched2_report.py', 'sched2_model.py', 'admission seed first deferred', 'admission hold reading reused', 'admission ledger trim', 'ESTIMATE', '15.4 s -> about 12.7 s', 'agent_turns', 'control-to-control floor'):
            self.assertIn(phrase, text)
        for name, phrase in (('SE1-seed-a', "built lines' ms"), ('HO1-hold-a', 'hold reading reused'), ('LT1-ledger-a', 'op=rebind bracket')):
            self.assertIn(phrase, re.sub(r'\s*\n#\s*', ' ', (PACK / (name + '.env')).read_text(encoding='utf-8')), name)

    def test_the_estimates_in_the_templates_are_the_models(self):
        """The pack quotes sched2_model's arithmetic; a change to the model that moves the headline numbers must change the pack."""
        import sched2_model as model

        base, everything = model.replay()[-1], model.replay(('hold', 'ledger', 'seed'))[-1]
        self.assertAlmostEqual(base, 15.4, delta=0.1)
        self.assertAlmostEqual(everything, 12.7, delta=0.1)
        self.assertAlmostEqual(model.amplified(('hold', 'ledger', 'seed'))[-1], 11.8, delta=0.1)
        self.assertAlmostEqual(model.returning(('hold', 'ledger', 'seed')) / 1000.0, 1.12, delta=0.02)
        self.assertAlmostEqual(base - model.replay(('ledger',))[-1], 1.7, delta=0.1)
        self.assertAlmostEqual(base - model.replay(('hold',))[-1], 0.65, delta=0.1)

    def test_the_tools_the_templates_name_exist(self):
        for tool in ('sched2_report.py', 'sched2_model.py', 'agent_turns.py', 'qwen_c2_checkpoint.py'):
            self.assertTrue((HERE / tool).is_file(), tool)


class GeneratedTests(unittest.TestCase):
    def test_the_checked_in_pack_is_what_the_generator_makes(self):
        self.assertEqual(pack.main(['--check']), 0)

    def test_nothing_in_the_pack_names_a_host_an_address_or_a_registry(self):
        for path in PACK.glob('*'):
            text = path.read_text(encoding='utf-8')
            with self.subTest(path=path.name):
                self.assertEqual([needle for needle in ('/home/', 'zot.', 'ghcr', 'docker.io', '.local', '.internal', 'localhost') if needle in text], [])
                self.assertIsNone(re.search(r'\b(?:\d{1,3}\.){3}\d{1,3}\b', text), 'an IP address')
                self.assertIsNone(re.search(r'blackhole-[0-9A-F]{16}', text), 'a card id')
                self.assertIsNone(re.search(r'\bsha256:[0-9a-f]{12,}', text), 'an image digest')


if __name__ == '__main__':
    unittest.main()
